<section id="credits-view" hidden aria-labelledby="credits-title">
    <div class="section-heading"><div><h1 id="credits-title">Crédito y abonos</h1><p id="credits-scope" class="hint"></p></div><button id="credits-configure" class="secondary" data-icon="pen-to-square" type="button" hidden>Configurar crédito de un cliente</button></div>
    <p id="credits-message" role="status" aria-live="polite"></p>
    <section id="credits-list"><form id="credits-search-form" class="report-filters"><div><label for="credits-search">Cliente o folio de venta</label><input id="credits-search" maxlength="100" type="search" placeholder="Nombre o V-00000001"></div><div><label for="credits-state">Estado</label><select id="credits-state"><option value="pendiente">Con saldo pendiente</option><option value="todos">Todos los créditos</option></select></div><button class="primary" data-icon="magnifying-glass" type="submit">Buscar</button></form><div class="table-scroll"><table><thead><tr><th>Venta / cliente</th><th>Crédito original</th><th>Saldo pendiente</th><th>Vencimiento</th><th>Acciones</th></tr></thead><tbody id="credits-rows"></tbody></table></div><button id="credits-more" class="secondary" type="button" hidden>Cargar más</button></section>
    <section id="credits-detail" hidden><div class="section-heading"><h2 id="credit-detail-title"></h2><button id="credit-back" class="secondary" data-icon="arrow-left" type="button">Volver a créditos</button></div><p id="credit-detail-summary"></p><p class="hint">Sin intereses. El vencimiento se fijó al vender. Los abonos no se editan ni se eliminan. Las devoluciones reducen primero la deuda pendiente y después permiten reembolsar pagos recibidos.</p>
        <form id="credit-payment-form"><fieldset id="credit-payment-fields" class="adjust-fields"><h3>Registrar abono</h3><p id="credit-payment-help" class="hint"></p><div class="product-fields"><div><label for="credit-turn">Mi caja abierta</label><select id="credit-turn" required></select></div><div><label for="credit-method">Método de pago</label><select id="credit-method" required></select></div><div><label for="credit-amount">Importe del abono</label><input id="credit-amount" type="number" step=".01" min=".01" required></div><div id="credit-received-field"><label for="credit-received">Efectivo recibido (opcional)</label><input id="credit-received" type="number" step=".01" min="0" max="999999999999.99"></div><div><label for="credit-reference">Referencia (opcional)</label><input id="credit-reference" maxlength="100"></div></div><p id="credit-change" class="hint"></p><label class="check-label"><input id="credit-confirm" type="checkbox" required> Confirmo que recibí este pago y quiero aplicarlo a esta venta.</label></fieldset><p id="credit-payment-error" class="message" role="alert"></p><button id="credit-pay" class="primary" data-icon="check" type="submit">Registrar abono</button></form>
        <h3>Historial de abonos</h3><div id="credit-history"></div><h3>Devoluciones y ajustes de deuda</h3><div id="credit-adjustments"></div>
    </section>
    <section id="credit-config" hidden><div class="section-heading"><h2>Habilitar crédito por cliente</h2><button id="credit-config-back" class="secondary" data-icon="arrow-left" type="button">Volver a créditos</button></div><p class="hint">Solo el administrador cambia estos límites. Se requiere un cliente registrado distinto del predeterminado. Deshabilitar crédito impide nuevas ventas a crédito y permite seguir recibiendo abonos.</p><form id="credit-client-search-form" class="report-filters"><div><label for="credit-client-search">Buscar cliente registrado</label><input id="credit-client-search" maxlength="100" type="search"></div><button class="secondary" data-icon="magnifying-glass" type="submit">Buscar cliente</button></form><div id="credit-client-options"></div>
        <form id="credit-config-form" hidden><h3 id="credit-config-client"></h3><p id="credit-config-balance" class="hint"></p><fieldset id="credit-config-fields" class="adjust-fields"><div class="product-fields"><div><label for="credit-enabled">Crédito</label><select id="credit-enabled"><option value="0">Deshabilitado</option><option value="1">Habilitado</option></select></div><div><label for="credit-limit">Límite total de crédito</label><input id="credit-limit" type="number" min="0" max="999999999999.99" step=".01" required></div><div><label for="credit-days">Plazo en días para nuevas ventas</label><input id="credit-days" type="number" min="1" max="365" step="1" required></div></div></fieldset><p id="credit-config-error" class="message" role="alert"></p><button id="credit-config-save" class="primary" data-icon="floppy-disk" type="submit">Guardar límite y plazo</button></form>
    </section>
    <div id="credit-receipt" class="ticket-paper" hidden></div>
</section>
